//! C-F3 · F3.1: contratos RED del consenso espectral. Eventos sintéticos, sin red.
use god_engine_core::GodEngineCore;
use quantum_arena::temporal_spectrum::TAU_ANCHOR_FAST_MS;
use quantum_arena::{symbol_registry, symbols, GlobalArena};
use signal_engine::SignalType;
use std::sync::Arc;

const SIM: &str = "CF3ESPUSDT";
const T0: u64 = 1_700_000_000_000;

struct Lcg(u64);
impl Lcg {
    fn u(&mut self) -> f64 {
        self.0 = self
            .0
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        ((self.0 >> 11) as f64 + 0.5) / (1u64 << 53) as f64
    }
    fn n(&mut self) -> f64 {
        let (u1, u2) = (self.u(), self.u());
        (-2.0 * u1.ln()).sqrt() * (2.0 * std::f64::consts::PI * u2).cos()
    }
}

fn nucleo() -> (Arc<GlobalArena>, GodEngineCore) {
    symbols::update_dynamic_universe(vec![SIM.into()]);
    symbol_registry::update_registry(vec![symbol_registry::get_official_binance_spec(SIM)]);
    let arena = GlobalArena::build_in_own_stack(100.0);
    let mut core = GodEngineCore::new(arena.clone());
    core.swing_nn = None;
    core.scalp_forest = None;
    (arena, core)
}

/// Evento de profundidad puro: actualiza el espectro (lib.rs:1740) y compone
/// el consenso de 13 motores (lib.rs:1963-2590). No abre posiciones (:2793).
fn profundidad(core: &mut GodEngineCore, mid: f64, t_ms: u64) {
    let medio = mid * 0.5e-4;
    let _ = core.process_event(
        0, false, false, true, mid, 0.0, mid - medio, mid + medio, 5.0, 5.0, 0.0, 0.0,
        t_ms, false, &[0.0; 54], false,
    );
}

#[test]
fn cf3_en_ruido_el_veredicto_espectral_no_decide() {
    let (arena, mut core) = nucleo();
    let mut rng = Lcg(0xF31_0001);
    let mut mid = 100.0f64;
    let (mut activas, mut decididas) = (0usize, 0usize);
    for i in 0..7_200u64 {
        // Martingala: ninguna señal tiene IC distinto de 0; decidir aquí es coste sin ventaja.
        mid *= 1.0 + 2e-4 * rng.n();
        profundidad(&mut core, mid, T0 + i * 1_000);
        if i < 600 {
            continue;
        }
        let v = arena.registry.get_for_coin_or(0, "consenso_espectral_dominante", 0.0);
        let tau = arena.registry.get_for_coin_or(0, "consenso_espectral_tau", 0.0);
        if v.abs() > 1e-9 && tau >= TAU_ANCHOR_FAST_MS {
            activas += 1;
            let d = core
                .tensor_orchestrator
                .evaluate_continuous_consensus_for_coin(0, SIM);
            if d.signal != SignalType::Flat {
                decididas += 1;
            }
        }
    }
    assert!(activas >= 50, "el veredicto espectral apenas se activó ({activas}); prueba no concluyente");
    let frac = decididas as f64 / activas as f64;
    assert!(
        frac <= 0.05,
        "en ruido puro el veredicto espectral decide en {:.1} % de las evaluaciones activas ({decididas}/{activas})",
        100.0 * frac
    );
}

