#[test]
fn cf3_el_dominante_no_sale_de_una_escala_no_observada() {
    let (arena, mut core) = nucleo();
    let mut rng = Lcg(0xF31_0002);
    let mut mid = 100.0f64;
    let (mut con_voto, mut violaciones) = (0usize, 0usize);
    let mut peor_razon = 0.0f64;
    for i in 0..7_200u64 {
        mid *= 1.0 + 2e-4 * rng.n();
        let t = T0 + i * 1_000;
        profundidad(&mut core, mid, t);
        if i < 1_800 {
            continue; // 30 min de calentamiento
        }
        let v = arena.registry.get_for_coin_or(0, "consenso_espectral_dominante", 0.0);
        let tau = arena.registry.get_for_coin_or(0, "consenso_espectral_tau", 0.0);
        let transcurrido = (t - T0) as f64;
        if v.abs() > 1e-9 {
            con_voto += 1;
            if tau > transcurrido {
                violaciones += 1;
                peor_razon = peor_razon.max(tau / transcurrido);
            }
        }
    }
    assert!(con_voto > 0, "el consenso no produjo ningún dominante");
    assert_eq!(
        violaciones, 0,
        "{violaciones}/{con_voto} dominantes con τ mayor que el tiempo observado (peor τ/transcurrido = {peor_razon:.1})"
    );
}

use quantum_arena::temporal_spectrum::{SPECTRUM_SCALES_MS, TAU_ANCHOR_FAST_MS, TAU_ANCHOR_SLOW_MS};
use signal_engine::skill_motores::ttl_consenso_ms;

#[test]
fn cf3_ttl_del_veredicto_no_supera_la_vida_que_fija_el_orquestador() {
    for (k, &tau) in SPECTRUM_SCALES_MS.iter().enumerate() {
        let ttl = ttl_consenso_ms(tau) as f64;
        // orchestrator.rs:576-587: la posición vive min(τ, 12 h), y el escalar nunca menos de 30 s.
        let vida = tau.min(TAU_ANCHOR_SLOW_MS).max(TAU_ANCHOR_FAST_MS);
        assert!(
            ttl <= vida + 1.0,
            "escala {k}: τ = {tau:.3e} ms, TTL {ttl:.3e} ms > vida {vida:.3e} ms"
        );
    }
}

use omniscient_registry::OmniscientRegistry;
use quantum_arena::GlobalArena;
use signal_engine::orchestrator::TensorVoteOrchestrator;
use signal_engine::SignalType;
use std::sync::Arc;
use strategy_core::QuantumStrategy;

struct Fija(f64, &'static str);
impl QuantumStrategy for Fija {
    fn name(&self) -> &str {
        self.1
    }
    fn init(&mut self, _r: Arc<OmniscientRegistry>) -> Result<(), String> {
        Ok(())
    }
    fn evaluate(&self) -> f64 {
        self.0
    }
}

fn decide(votos: &[f64]) -> (bool, f64) {
    const NOMBRES: [&str; 4] = ["cf3_fija_a", "cf3_fija_b", "cf3_fija_c", "cf3_fija_d"];
    let mut o = TensorVoteOrchestrator::new(GlobalArena::build_in_own_stack(13.0));
    for (i, &v) in votos.iter().enumerate() {
        o.add_strategy(Box::new(Fija(v, NOMBRES[i])));
    }
    let d = o.evaluate_continuous_consensus_for_coin(0, "CF3ESCUSDT");
    (d.signal == SignalType::Flat, d.net_confidence)
}

#[test]
fn cf3_un_voto_infinitesimal_no_compra_conviccion() {
    let (plano, c) = decide(&[2e-9]);
    assert!(
        plano || c < 1e-6,
        "un único voto de 2e-9 produce una decisión (plano = {plano}) con confianza {c:.3}"
    );
    let (_, c_debil) = decide(&[0.002, 0.002]);
    let (_, c_fuerte) = decide(&[0.9, 0.9]);
    assert!(
        c_debil <= 0.1 * c_fuerte,
        "votos 0,002 dan {c_debil:.3} y votos 0,9 dan {c_fuerte:.3}: la convicción no escala con la evidencia"
    );
}

// Mismo archivo: usa nucleo(), Lcg, profundidad() y T0 definidos arriba.
fn soliton_con_ofi(ofi: f64) -> f64 {
    let (arena, mut core) = nucleo();
    let mut rng = Lcg(0xF31_0005);
    let mut mid = 100.0f64;
    for i in 0..1_800u64 {
        mid *= 1.0 + 2e-4 * rng.n();
        // La sombra lee el OFI antes de que process_tick_dual lo reescriba (lib.rs:2097 < :2802).
        arena.registry.set_for_coin(0, "order_flow_imbalance", ofi);
        profundidad(&mut core, mid, T0 + i * 1_000);
    }
    arena.registry.get_for_coin_or(0, "sombra_soliton_amplitud_max", f64::NAN)
}

#[test]
fn cf3_el_soliton_espectral_es_par_en_el_signo_del_ofi() {
    use signal_engine::soliton_wave::SolitonWaveEngine as S;
    // Referencia: el motor vivo es par en el signo de la amplitud (abs en soliton_wave.rs:33-37).
    assert_eq!(
        S::compute_soliton_amplitude(0.5, 0.0, 0.3, 0.05),
        S::compute_soliton_amplitude(-0.5, 0.0, 0.3, 0.05)
    );
    let mut x = [0.0f64; 32];
    for (k, xi) in x.iter_mut().enumerate() {
        *xi = (k as f64 - 15.5) / 8.0;
    }
    let pos = S::voto_espectral(&x, 0.5);
    let neg = S::voto_espectral(&x, -0.5);
    for k in 0..32 {
        assert!(
            (pos.en_escala(k) - neg.en_escala(k)).abs() < 1e-12,
            "escala {k}: {} con OFI +0,5 frente a {} con OFI -0,5",
            pos.en_escala(k),
            neg.en_escala(k)
        );
    }
    let (a, b) = (soliton_con_ofi(0.5), soliton_con_ofi(-0.5));
    assert!(a.is_finite() && b.is_finite(), "la sombra no publicó su amplitud");
    assert!((a - b).abs() < 1e-12, "amplitud dominante {a} (OFI +0,5) frente a {b} (OFI -0,5)");
}

