//! C-F3 / F3.2 — una sola τ de punta a punta. Borrador, sin dependencias nuevas.
use god_engine_core::GodEngineCore;
use quantum_arena::{GlobalArena, symbol_registry};
use signal_engine::SignalType;
use std::sync::{Arc, Mutex, atomic::Ordering::Relaxed};

static ENTORNO: Mutex<()> = Mutex::new(());

/// Cierres de la serie T-1 (backtest-engine/tests/support/t1_measurement.rs:7-33).
fn serie_t1(n: usize) -> Vec<f64> {
    let mut seed = 0x5DEECE66Du64;
    let mut p = 60_000.0f64;
    (0..n)
        .map(|i| {
            seed = seed
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            let u = ((seed >> 33) as f64 / u32::MAX as f64) - 0.5;
            p *= 1.0 + (i as f64 / 180.0).sin() * 0.0030 + u * 0.0040 + 0.00004;
            p
        })
        .collect()
}

fn nucleo() -> (Arc<GlobalArena>, GodEngineCore) {
    quantum_arena::symbols::update_dynamic_universe(vec!["XXIXUSDT".into()]);
    symbol_registry::update_registry(vec![symbol_registry::get_official_binance_spec("XXIXUSDT")]);
    let arena = GlobalArena::build_in_own_stack(1_000.0);
    let core = GodEngineCore::new(arena.clone());
    (arena, core)
}

/// 12 eventos de depth por minuto; el último cierra la vela de 1 min.
fn recorrer(core: &mut GodEngineCore, mut cada_evento: impl FnMut(&mut GodEngineCore, bool)) {
    let mut t = 1_700_000_000_000u64;
    for p in serie_t1(4 * 24 * 60) {
        for j in 0..12u64 {
            t += 5_000;
            let (bid, ask) = (p * 0.9998, p * 1.0002);
            let (entrada, _) = core.process_event(
                0, false, j == 11, true, p, 0.0, bid, ask, 5.0, 5.0, 0.0, 0.0, t, false, &[0.0; 54], false,
            );
            cada_evento(core, entrada.is_some());
        }
    }
}

#[test]
fn cf3_la_tau_que_juzga_qo586_es_la_tau_de_la_orden() {
    let _g = ENTORNO.lock().unwrap_or_else(|p| p.into_inner());
    let (arena, mut core) = nucleo();
    let mut ordenes = 0usize;
    let mut abiertas: Vec<bool> = arena.coins[0].positions.slots().iter().map(|s| s.is_open()).collect();
    recorrer(&mut core, |core, hubo_orden| {
        let ahora: Vec<bool> = arena.coins[0].positions.slots().iter().map(|s| s.is_open()).collect();
        if hubo_orden {
            // τ que juzgaron QO-586 y el co-despacho (guardadas en lib.rs:6702-6706).
            let juzgadas: Vec<f64> = [&core.last_fast_intent[0], &core.last_slow_intent[0]]
                .iter()
                .filter(|i| i.signal != SignalType::Flat && i.expected_duration_ms > 0)
                .map(|i| i.expected_duration_ms as f64)
                .collect();
            for (k, s) in arena.coins[0].positions.slots().iter().enumerate() {
                if ahora[k] && !abiertas[k] {
                    ordenes += 1;
                    let tau_orden = s.entry_tau_ms.load(Relaxed) as f64;
                    assert!(
                        juzgadas.iter().any(|&tj| (tau_orden - tj).abs() <= 1e-6 * tj),
                        "la orden vive a τ = {tau_orden} ms y las puertas juzgaron {juzgadas:?}"
                    );
                }
            }
        }
        abiertas = ahora;
    });
    assert!(ordenes > 0, "precondición: la cinta T-1 debe abrir al menos una orden");
}

// Mismo archivo que la prueba anterior: reutiliza ENTORNO, nucleo() y recorrer().
#[test]
fn cf3_la_rama_11_vive_a_la_escala_que_hablo() {
    let _g = ENTORNO.lock().unwrap_or_else(|p| p.into_inner());
    let (arena, mut core) = nucleo();
    let mut vistos = 0usize;
    recorrer(&mut core, |core, _| {
        let fi = &core.last_fast_intent[0];
        if fi.signal == SignalType::Flat || fi.volume_flow_rate != 11.0 {
            return;
        }
        let tau_k = arena.registry.get_for_coin_or(0, "consenso_espectral_tau", 0.0);
        let v = arena.registry.get_for_coin_or(0, "consenso_espectral_dominante", 0.0);
        if v == 0.0 || tau_k < 30_000.0 {
            return;
        }
        vistos += 1;
        let esperado = tau_k.min(43_200_000.0);
        let actual = fi.expected_duration_ms as f64;
        assert!(
            (actual - esperado).abs() <= 1e-6 * esperado,
            "la rama 11 decide a τ_k = {tau_k} ms y viaja a {actual} ms"
        );
    });
    assert!(vistos > 0, "precondición: alguna intención de la rama 11 con consenso en banda");
}

