fn p_primer_toque(tau_ms: u64) -> f64 {
    let arena = arena_btc(1_000.0);
    let mut risk = RiskEngine::new(1_000.0);
    let sl = 0.5 * 0.004 * (tau_ms as f64 / 60_000.0).sqrt();
    let tp = 2.25 * sl;
    arena.registry.set_for_coin(0, "p_hit_sl_first", -1.0);
    let intent = SignalIntent {
        signal: SignalType::Long,
        confidence: 0.80,
        win_probability: 0.60,
        tp_price_target: 60_000.0 * (1.0 + tp),
        sl_price_target: 60_000.0 * (1.0 - sl),
        expected_duration_ms: tau_ms,
        ..SignalIntent::default()
    };
    risk.evaluate_quantum_order(0, &intent, &arena);
    let p = arena.registry.get_for_coin_or(0, "p_hit_sl_first", -1.0);
    assert!(p >= 0.0, "precondición: la orden a τ = {tau_ms} ms debe llegar a R-15 (p = {p})");
    p
}

#[test]
fn cf3_r15_primer_toque_invariante_en_tau_con_brackets_brownianos() {
    let base = p_primer_toque(300_000);
    assert!((base - 0.762).abs() < 0.005, "solución conocida a 300 s: {base}");
    for tau in [1_200_000u64, 14_400_000, 43_200_000] {
        let p = p_primer_toque(tau);
        assert!((p - base).abs() < 1e-9, "τ = {tau} ms: P = {p} frente a {base} a 300 s");
    }
}

