};

static ENVIRONMENT: Mutex<()> = Mutex::new(());

struct FixtureDirectory {
    root: PathBuf,
    previous: PathBuf,
}
impl FixtureDirectory {
    fn new() -> Self {
        let stamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!("tg-cf3-close-{}-{stamp}", std::process::id()));
        std::fs::create_dir(&root).unwrap();
        std::fs::create_dir(root.join("data")).unwrap();
        let previous = std::env::current_dir().unwrap();
        std::env::set_current_dir(&root).unwrap();
        Self { root, previous }
    }
}
impl Drop for FixtureDirectory {
    fn drop(&mut self) {
        std::env::set_current_dir(&self.previous).unwrap();
        let exact = self.root.canonicalize().unwrap();
        assert!(exact.starts_with(std::env::temp_dir().canonicalize().unwrap()));
        assert!(exact.file_name().unwrap().to_string_lossy().starts_with("tg-cf3-close-"));
        std::fs::remove_dir_all(exact).unwrap();
    }
}

