//! F3.4-06 — el veto «absoluto» de DD del consejo debe ser alcanzable por debajo del corte del risk-engine.
use metacortex_engine::{ConsejoDeliberacion, MarketSnapshotPayload, SeniorRole};
use risk_engine::drawdown::{drawdown_de_falsacion, ALFA_FALSACION, FRACCION_KELLY_MAXIMA};

#[test]
fn cf3_veto_dd_consejo_alcanzable() {
    let d_star = drawdown_de_falsacion(FRACCION_KELLY_MAXIMA, ALFA_FALSACION);
    assert!(d_star.is_finite() && d_star > 0.0 && d_star < 1.0, "d* = {d_star}");
    // El risk-engine rechaza con dd ≥ umbral ≤ d* ANTES del consejo (lib.rs:7581-7596), con el
    // mismo capital y el mismo pico: el mayor DD que el consejo puede ver es menor que d*.
    let dd = d_star * 0.999;
    let consejo = ConsejoDeliberacion::new();
    let alcanzable = [30_000.0_f64, 600_000.0, 3_600_000.0, 43_200_000.0].iter().any(|&tau| {
        let p = MarketSnapshotPayload {
            intended_direction: 1.0,
            current_drawdown_pct: dd,
            dominant_tau_ms: tau,
            ..Default::default()
        };
        consejo.deliberar(&p, 0.5).vetoed_by == Some(SeniorRole::Riesgo)
    });
    assert!(alcanzable, "el veto de DD del consejo (0,95 − 0,10·s) no se alcanza bajo d* = {d_star:.3}");
}

