    let snap = core.ensembles[0].prediction_snapshot();
    assert!(snap[0].is_some() && snap[1].is_some(), "precondición: opinan los dos modelos {snap:?}");
    let p = arena.registry.get_for_coin_or(0, "ml_prob_motor", f64::NAN);
    let b = arena.registry.get_for_coin_or(0, "ml_model_base", f64::NAN);
