/// Formulas del escritor (lib.rs:4475, :4506-4512) con last_price = mid.
fn registro_coaxial(p0: f64, v_t: f64) -> Arc<OmniscientRegistry> {
    let atr_pct = v_t / p0;
    let micro_v = (v_t / p0).clamp(atr_pct * 0.1, atr_pct * 5.0);
    let r = Arc::new(OmniscientRegistry::new());
    publicar(&r, "atr_pct", atr_pct);
    publicar(&r, "atr_1s", (micro_v * p0).max(0.0001));
    publicar(&r, "atr_5s", (v_t * 0.5 + atr_pct * p0 * 0.5).max(0.0005));
    publicar(&r, "atr_1m", (atr_pct * p0 * 7.746).max(0.0020));
    publicar(&r, "order_flow_direction", 1.0);
    r
}

