    let arena = GlobalArena::build_in_own_stack(100.0);
    let mut core = GodEngineCore::new(arena.clone());
    core.swing_nn = None;
    core.scalp_forest = None;
    let omni = [0.0f64; 54];
    let libros = [(10.0, 2.0), (100.0, 20.0), (2.0, 10.0), (6.0, 6.0), (1.0, 50.0), (500.0, 100.0)];
    let mut t: u64 = 1_700_000_000_000;
    let (mut escritos, mut max_dev) = (0usize, 0.0f64);
    for i in 0..120usize {
        let (bq, aq) = libros[i % libros.len()];
        let mid = 100.0 + (i as f64 * 0.37).sin();
        t += 250 + (i as u64 % 7) * 900;
        let _ = core.process_tick_dual(0, mid - 0.01, mid + 0.01, bq, aq, t, &omni, false, false);
        let obi = arena.registry.get_for_coin_or(0, "order_book_imbalance", f64::NAN);
        let ent = arena.registry.get_for_coin_or(0, "tsallis_q_entropy", f64::NAN);
        if obi.is_finite() && ent.is_finite() {
            escritos += 1;
            max_dev = max_dev.max((ent - h(obi)).abs());
        }
    }
    assert!(escritos > 0, "arnes: el escritor de lib.rs:4451-4523 no corrio");
    assert!(
        max_dev > 1e-6,
        "la entropia publicada es una funcion exacta de OBI (desviacion maxima {:e}): el votante no aporta otra fuente",
        max_dev
    );
}

