//! CF3 F3.7-08: un evento de libro estacionario no debe asignar memoria.
use god_engine_core::GodEngineCore;
use quantum_arena::{symbol_registry, symbols, GlobalArena};
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};

struct Contador;
static ACTIVO: AtomicBool = AtomicBool::new(false);
static N: AtomicU64 = AtomicU64::new(0);

unsafe impl GlobalAlloc for Contador {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 {
        if ACTIVO.load(Ordering::Relaxed) { N.fetch_add(1, Ordering::Relaxed); }
        System.alloc(l)
    }
    unsafe fn alloc_zeroed(&self, l: Layout) -> *mut u8 {
        if ACTIVO.load(Ordering::Relaxed) { N.fetch_add(1, Ordering::Relaxed); }
        System.alloc_zeroed(l)
    }
    unsafe fn realloc(&self, p: *mut u8, l: Layout, n: usize) -> *mut u8 {
        if ACTIVO.load(Ordering::Relaxed) { N.fetch_add(1, Ordering::Relaxed); }
        System.realloc(p, l, n)
    }
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
        System.dealloc(p, l)
    }
}

#[global_allocator]
static ASIGNADOR: Contador = Contador;

#[test]
fn cf3_evento_de_libro_estacionario_no_asigna() {
    symbols::update_dynamic_universe(vec!["BTCUSDT".into()]);
    symbol_registry::update_registry(vec![symbol_registry::get_official_binance_spec("BTCUSDT")]);
    let arena = GlobalArena::build_in_own_stack(100.0);
    let mut core = GodEngineCore::new(arena.clone());
    core.swing_nn = None;
    core.scalp_forest = None;
    let mut ts = 1_000u64;
    let mut libro = |core: &mut GodEngineCore, k: u64, ts: u64| {
        let mid = 50_000.0 + if k % 2 == 0 { 1.0 } else { -1.0 };
        let _ = core.process_event(0, false, false, true, mid, 0.0, mid - 0.5, mid + 0.5, 1.0, 1.0, 0.0, 0.0, ts, false, &[0.0; 54], false);
    };
    for k in 0..2_000u64 {
        libro(&mut core, k, ts);
        ts += 1_000;
    }
    N.store(0, Ordering::SeqCst);
    ACTIVO.store(true, Ordering::SeqCst);
    for k in 0..1_000u64 {
        libro(&mut core, k, ts);
        ts += 1_000;
    }
    ACTIVO.store(false, Ordering::SeqCst);
    let total = N.load(Ordering::SeqCst);
    assert!(total < 1_000, "asignaciones en 1 000 eventos de libro: {total}");
}

use god_engine_core::{calibration::normalized_directional_divergence, ml_inference::{NanoForest, NanoForestData}, GodEngineCore};
