    assert!((leer(&arena, "ml_prob") - BASE).abs() < 1e-6);
    let (pl, ps) = (leer(&arena, "conformal_p_value"), leer(&arena, "conformal_p_value_short"));
    assert!(pl < 1.0, "calibrador en calentamiento: el test no discriminaria");
    assert_eq!(pl, ps, "K-26: en neutralidad los dos lados comparten p-valor");
    assert_eq!(leer(&arena, "conformal_accept_long"), leer(&arena, "conformal_accept_short"));
}

// Reutiliza el preambulo (imports, CORE_ENV, nucleo_caliente, leer, tick) de cf3_k26_neutral_con_base_honesta_ejecutando_el_nucleo.
#[test]
fn cf3_espejo_del_sesgo_spot_con_base_honesta() {
    let _g = CORE_ENV.lock().unwrap_or_else(|p| p.into_inner());
    let lectura = |bps: f64| {
        let (arena, mut core) = nucleo_caliente();
        tick(&arena, &mut core, Some(bps));
        (leer(&arena, "ml_prob"), leer(&arena, "ml_model_base"),
         leer(&arena, "conformal_p_value"), leer(&arena, "conformal_p_value_short"))
    };
    let (ml_a, b_a, pl_a, ps_a) = lectura(5.0);
    let (ml_b, b_b, pl_b, ps_b) = lectura(-5.0);
    assert!((b_a - BASE).abs() < 1e-6 && (b_b - BASE).abs() < 1e-6);
    let d_a = normalized_directional_divergence(ml_a, b_a);
    let d_b = normalized_directional_divergence(ml_b, b_b);
    assert!((d_a + d_b).abs() < 1e-6, "mismo basis en espejo, apoyo distinto: d_A={d_a} d_B={d_b}");
    assert_eq!(pl_a, ps_b, "p-valor del largo con +5 pb frente al del corto con -5 pb");
    assert_eq!(ps_a, pl_b);
}

