#[cfg(test)]
mod tests_cf3_puertas_espejo {
    use super::*;
    use signal_engine::{SignalIntent, SignalType};
    use std::sync::Arc;

    fn intencion(s: SignalType) -> SignalIntent {
        SignalIntent { signal: s, confidence: 0.80, horizon: strategy_core::TradeHorizon::Continuous, ..Default::default() }
    }
    /// P(TP del largo antes que SL) bajo browniano con deriva: la fisica del propio repo.
    fn p_largo(mu: f64) -> f64 {
        1.0 - risk_engine::tp_sl::probabilidad_tocar_sl_antes_de_tp(0.0036, 0.0018, mu, 0.0018)
    }
    fn nucleo() -> (Arc<quantum_arena::GlobalArena>, GodEngineCore) {
        let arena = quantum_arena::GlobalArena::build_in_own_stack(13.0);
        let core = GodEngineCore::new(Arc::clone(&arena));
        arena.coins[0].agg_buy_vol.store(50.0, Ordering::Relaxed);
        arena.coins[0].agg_sell_vol.store(50.0, Ordering::Relaxed);
        (arena, core)
    }

    #[test]
    fn cf3_puertas_espejo_bajo_primer_toque() {
        let (_arena, core) = nucleo();
        let base = p_largo(0.0); // 1/3: base de la etiqueta TP = 2 SL
        for &mu in &[1e-4, 4e-4, -1.1e-3] {
            let l = core.puertas_del_continuo(0, intencion(SignalType::Long), true, 0.5, p_largo(mu), base, 0.0);
            let c = core.puertas_del_continuo(0, intencion(SignalType::Short), true, -0.5, p_largo(-mu), base, 0.0);
            assert_eq!(l.signal == SignalType::Flat, c.signal == SignalType::Flat, "mu={mu}: veto en un solo lado");
            assert!((l.confidence - c.confidence).abs() < 1e-9, "mu={mu}: largo {} frente a corto {}", l.confidence, c.confidence);
        }
    }
}

#[test]
fn cf3_puertas_y_gate_ml_leen_la_misma_base() {
    let (_arena, core) = nucleo();
    // El nucleo publica la base ya recortada a [0,05; 0,95] (lib.rs:4671-4675).
    let (base, p) = (0.05, 0.04);
    // Lo que mide el gate ML (lib.rs:7862-7865) con esa misma base.
    let d_gate = crate::calibration::normalized_directional_divergence(p, base);
    assert!((d_gate + 0.2).abs() < 1e-12);
    let out = core.puertas_del_continuo(0, intencion(SignalType::Long), true, 0.5, p, base, 0.0);
    assert_eq!(out.signal, SignalType::Long, "las puertas caen a base 0,5 (d = -0,92) y vetan");
    assert!((out.confidence - 0.80 * (1.0 + 0.5 * d_gate)).abs() < 1e-12);
}
